input.command:
mkdir -p force-app/main/default/lwc/helloWorld && cat > force-app/main/default/lwc/helloWorld/helloWorld.js << 'EOF'
import { LightningElement, api } from "lwc";

export default class extends LightningElement {
  @api objectApiName;

  get computedClassNames() {
    return [
      "slds-box",
      "slds-theme_alert-texture",
      this.objectApiName === 'Account' ? "slds-theme_shade" : "slds-theme_success"
    ];
  }
}
EOF

cat > force-app/main/default/lwc/helloWorld/helloWorld.html << 'EOF'
<template>
  <div class={computedClassNames}>Hello, World!</div>
</template>
EOF

cat > force-app/main/default/lwc/helloWorld/helloWorld.js-meta.xml << 'EOF'
<?xml version="1.0" encoding="UTF-8"?>
<LightningComponentBundle xmlns="http://soap.sforce.com/2006/04/metadata" fqn="helloWorld">
    <apiVersion>63.0</apiVersion>
    <isExposed>true</isExposed>
    <targets>
    <target>lightning__RecordPage</target>
    </targets>
</LightningComponentBundle>
EOF

ls -la force-app/main/default/lwc/helloWorld/
